{
  "items": [
    {
      "name": "Finset.abs_sum_le_sum_abs",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {G : Type u_9} [inst : AddCommGroup G] [inst_1 : LinearOrder G] [IsOrderedAddMonoid G] (f : ι → G)\n  (s : Finset ι), |∑ i ∈ s, f i| ≤ ∑ i ∈ s, |f i|"
    },
    {
      "name": "Polynomial.cauchyBound_zero",
      "module_name": "Mathlib.Analysis.Polynomial.CauchyBound",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : NormedDivisionRing K], Polynomial.cauchyBound 0 = 1"
    },
    {
      "name": "nat_abs_sum_le",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} (s : Finset ι) (f : ι → ℤ), (∑ i ∈ s, f i).natAbs ≤ ∑ i ∈ s, (f i).natAbs"
    },
    {
      "name": "AbsoluteValue.sum_le",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Ring.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {R : Type u_2} {S : Type u_3} [inst : Semiring R] [inst_1 : Semiring S] [inst_2 : PartialOrder S]\n  [IsOrderedRing S] (abv : AbsoluteValue R S) (s : Finset ι) (f : ι → R), abv (∑ i ∈ s, f i) ≤ ∑ i ∈ s, abv (f i)"
    },
    {
      "name": "Polynomial.norm_coeff_le_choose_mul_mahlerMeasure",
      "module_name": "Mathlib.Analysis.Polynomial.MahlerMeasure",
      "kind": "theorem",
      "type": "∀ (n : ℕ) (p : Polynomial ℂ), ‖p.coeff n‖ ≤ ↑(p.natDegree.choose n) * p.mahlerMeasure"
    }
  ]
}
